"use strict";
console.log("ledger-format starts");
const digits = require("ledger-digits");
console.log("ledger-format is ready");
exports.money = function money(cents) {
  const sign = cents < 0 ? "-" : "";
  const whole = Math.trunc(Math.abs(cents) / 100);
  const rest = String(Math.abs(cents) % 100).padStart(2, "0");
  return `${sign}${digits.group(whole)}.${rest} (grouping ${digits.groupings()})`;
};
